<script setup lang="ts">
import { gsap } from 'gsap'

interface Props {
  as?: 'h1' | 'h2' | 'h3' | 'div'
  color?: 'soy-sauce' | 'tamago' | 'shiro'
  background?: 'soy-sauce' | 'tamago' | 'shiro' | 'kodama'
  dir?: 'up' | 'down'
  reveal?: boolean
}

const props = withDefaults(defineProps<Props>(), {
  as: 'div',
  color: 'soy-sauce',
  background: 'shiro',
  dir: 'down',
  reveal: false,
})

const nameline = useTemplateRef('nameline')
const svgcontainer = useTemplateRef('nameline-svg-container')
const links = useTemplateRef('nameline-icon-links')
const arrow = useTemplateRef('nameline-arrow')

let ctx: gsap.Context

const setupGsap = () => {
  if (!props.reveal) return
  if (!nameline.value || !svgcontainer.value || !links.value || !arrow.value) return

  ctx = gsap.context(() => {
    gsap.timeline()
      .to(svgcontainer.value, {
        duration: 1.2,
        y: 0,
      })
      .to(links.value, {
        y: 0,
      })
      .to(arrow.value, {
        y: 0,
        autoAlpha: 1,
      }, '>0.1')
  }, nameline.value)
}

onMounted(() => setupGsap())

onUnmounted(() => ctx && ctx.revert())
</script>

